        { type: 'one', q: 'Человек ответил: «Спасибо, я сам справлюсь». Что делать?', a: ['Всё равно помочь силой', 'Уважать его решение', 'Обидеться', 'Спорить'], c: 1, why: 'Человек сам решает, нужна ли ему помощь.' },
        { type: 'one', q: 'Мурлок решил каждый день делать одно доброе дело. Что из этого — доброе дело?', a: ['Посмеяться над тем, кто ошибся', 'Взять чужую вещь без спроса', 'Промолчать, когда обижают малыша', 'Помочь бабушке донести сумку'], c: 3, why: 'Доброе дело — это помощь и забота о других. Даже маленькое ежедневное доброе дело делает мир вокруг теплее.' },
        { type: 'order', q: 'Как поддержать грустного друга? Расставь шаги', items: ['Заметить, что другу грустно', 'Подойти и спросить: «Что случилось?»', 'Выслушать, не перебивая', 'Сказать: «Я рядом, чем помочь?»'], why: 'Заметить → спросить → выслушать → предложить помощь.' },
        { type: 'sort', q: 'Поддерживает или нет?', groups: ['💛 Поддерживает', '💔 Не поддерживает'], items: [['Выслушать друга', 0], ['Позвать играть того, кого не берут', 0], ['Рассказать учителю, что кого-то обижают', 0], ['Сказать «Да ладно, ерунда!»', 1], ['Смеяться вместе со всеми над новеньким', 1], ['Пересказать секрет друга всему классу', 1]], why: 'Поддержка — слушать, звать в игру и защищать. Смеяться и выдавать секреты — обижать.' },
        { type: 'case', story: 'Одноклассницу Аню каждый день дразнят на перемене. Сегодня она расплакалась.', q: 'Что ты сделаешь?', a: [
          { t: 'Поддержу Аню и расскажу учителю', ok: true, why: 'Травлю останавливают взрослые, а поддержка друга очень важна.' },
          { t: 'Посмеюсь — это же просто шутка', ok: false, why: 'Если человек плачет, это уже не шутка.' },
          { t: 'Дразнить не буду, но промолчу', ok: 'mid', why: 'Не участвовать — хорошо, но Ане нужна помощь.' }
        ], why: 'Травля — не шутка: нужно поддержать и позвать взрослых.' },
        { type: 'tf', q: 'Рассказать взрослым, что кого-то травят, — это ябедничество.', c: false, why: 'Это помощь человеку в беде, а не ябедничество.' },
        { type: 'one', q: 'Что такое «добрый дневник»?', a: ['Тетрадь, куда записывают добрые дела', 'Дневник с оценками за хорошее поведение', 'Список подарков, которые хочется получить', 'Расписание уроков'], c: 0, why: 'Каждый вечер — одна запись о добром деле.' }
