  const rnd = n => Math.floor(Math.random() * n), pick = a => a[rnd(a.length)], shuf = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = rnd(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const one = (q, right, wrong, why) => { const a = shuf([right, ...wrong]); return { type: 'one', q, a, c: a.indexOf(right), why }; };
